import { useState } from "react";
//#region src/useCycleList/index.ts
const useCycleList = (list, i = 0) => {
	const [index, setIndex] = useState(i);
	const set = (i) => {
		setIndex((current) => {
			const length = list.length;
			if (length === 0) return current;
			return ((current + i) % length + length) % length;
		});
	};
	const next = (i = 1) => {
		set(i);
	};
	const prev = (i = 1) => {
		set(-i);
	};
	return [
		list[index],
		next,
		prev
	];
};
//#endregion
export { useCycleList };
